// DuckBot v2.3.0 - Enhanced News Video Response Handler
// Handles Discord webhook requests for news video generation
// Integrates with existing trading analysis data

const input = $input.first().json;
const command = input.command;
const isNewsVideoRequest = command === 'generate_news_video';

if (isNewsVideoRequest) {
    const prompt = input.prompt;
    const newsType = input.news_type || 'finance';
    const userId = input.user_id;
    const serverId = input.server_id;
    const userName = input.user_name;

    // Create Discord response embed
    const embed = {
        title: "📺 Enhanced Trading News Video Generated!",
        description: `**Content:** ${prompt}\n**Type:** ${newsType.toUpperCase()} News\n🎭 **Purple Sunshine news anchor integrated**\n📊 **Trading analysis data included**`,
        color: 0x00ff00,
        fields: [
            { name: "👤 Requested by", value: userName, inline: true },
            { name: "📺 News Type", value: newsType, inline: true },
            { name: "🎭 Enhancement", value: "Purple Sunshine Overlay", inline: true }
        ],
        timestamp: new Date().toISOString(),
        footer: { text: "DuckBot v2.3.0 - Enhanced Trading Video with Purple Sunshine" }
    };

    return {
        discord_response: { embeds: [embed] },
        webhook_response: true,
        news_video_request: true,
        user_id: userId,
        server_id: serverId,
        enhanced_prompt: `${prompt} - Trading analysis enhanced news report with Purple Sunshine anchor`,
        news_type: newsType
    };
} else {
    // Not a news video request, ignore this path
    return null;
}

// This node fetches cryptocurrency data for multiple symbols from the free CoinPaprika API.
// It does not require an API key.

// --- LOGIC ---

// Get the incoming item from the previous node.
// We expect an array of symbols, e.g., { "json": { "symbols": ["QUBIC", "BTC"] } }
const item = items[0];
const cryptoSymbols = item.json.symbols;

if (!cryptoSymbols || !Array.isArray(cryptoSymbols) || cryptoSymbols.length === 0) {
  throw new Error('No cryptocurrency symbols provided. Please provide an array of symbols in the "symbols" field.');
}

// --- Step 1: Fetch the entire coin list once to avoid multiple API calls ---
let allCoins;
try {
  console.log("Fetching the main coin list from CoinPaprika...");
  // FIX: Added 'json: true' to ensure the response is parsed as a JSON array.
  allCoins = await this.helpers.request({ uri: 'https://api.coinpaprika.com/v1/coins', json: true });
  console.log(`Found ${allCoins.length} coins.`);
} catch (error) {
  console.error("Error fetching coin list from CoinPaprika:", error.message);
  throw new Error('Could not connect to the CoinPaprika API to get the coin list.');
}

const allResults = [];

// --- Step 2: Loop through each symbol and get its data ---
for (const symbol of cryptoSymbols) {
  console.log(`Searching for symbol: ${symbol}`);

  // Find the specific coin that matches the user's symbol from the pre-fetched list
  const coinInfo = allCoins.find(c => c.symbol.toUpperCase() === symbol.toUpperCase());

  if (!coinInfo) {
    console.warn(`Could not find a coin with the symbol "${symbol}" on CoinPaprika. Skipping.`);
    continue; // Skip to the next symbol if not found
  }

  const coinId = coinInfo.id;
  console.log(`Found ID for ${symbol}: ${coinId}. Fetching ticker data...`);

  // Fetch the Ticker Data using the Coin ID
  let tickerData;
  try {
    // Also use json: true here for consistency
    tickerData = await this.helpers.request({ uri: `https://api.coinpaprika.com/v1/tickers/${coinId}`, json: true });
  } catch (error) {
    console.error(`Error fetching ticker data for ${coinId}:`, error.message);
    continue; // Skip if there's an error for this specific coin
  }

  // --- DATA PROCESSING ---
  const quote = tickerData.quotes.USD;
  const formattedData = {
    name: tickerData.name,
    symbol: tickerData.symbol,
    price: quote.price,
    price_formatted: `$${quote.price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 8 })}`,
    market_cap: quote.market_cap,
    market_cap_formatted: `$${Math.round(quote.market_cap).toLocaleString('en-US')}`,
    volume_24h: quote.volume_24h,
    percent_change_24h: quote.percent_change_24h,
    last_updated: tickerData.last_updated,
    paprika_url: `https://coinpaprika.com/coin/${coinId}/`
  };

  allResults.push(formattedData);
  console.log(`Successfully fetched and formatted data for ${symbol}.`);
}

// Replace the incoming data with a new object containing all our results
item.json.coin_data = allResults;

// Return the item to be used by the next node
return item;

// Tool Name: GetLiveCryptoPrices (n8n-safe)
// Description: Fetch real-time prices from CoinPaprika and return a STRING in `response`.
// Input (optional): `query` JSON string like {"symbols":["BTC","QUBIC","XMR"],"mode":"trending"}
// Output: { response: "<JSON string>" }  <-- response MUST be a string for n8n

// ---------- fetch polyfill for Node < 18 ----------
let _fetch = typeof fetch !== "undefined" ? fetch : null;
if (!_fetch) {
  _fetch = (...args) => import("node-fetch").then(({ default: f }) => f(...args));
}

// ---------- config & input parsing ----------
const DEFAULT_SYMBOLS = ["BTC", "QUBIC"];
const DEFAULT_MODE = "single"; // or "trending"

let symbols = [...DEFAULT_SYMBOLS];
let mode = DEFAULT_MODE;

try {
  if (typeof query === "string" && query.trim()) {
    const parsed = JSON.parse(query);
    if (Array.isArray(parsed.symbols) && parsed.symbols.length) symbols = parsed.symbols;
    if (parsed.mode) mode = String(parsed.mode);
  }
} catch {
  // ignore and use defaults
}

// ---------- helpers ----------
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function fetchJSON(url, opts = {}, retries = 2, backoffMs = 350) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    const res = await _fetch(url, {
      headers: { Accept: "application/json", "User-Agent": "n8n-psunshine/1.0" },
      ...opts,
    });
    if (res.ok) return res.json();
    if (res.status === 429 && attempt < retries) {
      await sleep(backoffMs * (attempt + 1));
      continue;
    }
    let text = "";
    try { text = await res.text(); } catch {}
    throw new Error(`HTTP ${res.status} on ${url}${text ? ` | ${text.slice(0,120)}...` : ""}`);
  }
}

/** Resolve coinpaprika coin_id for a symbol using /search then /coins as fallback */
async function resolveCoinId(symbol) {
  const sym = symbol.toUpperCase();

  // 1) /search (fast)
  try {
    const s = await fetchJSON(`https://api.coinpaprika.com/v1/search?q=${encodeURIComponent(sym)}&c=currencies&limit=10`);
    if (s?.currencies?.length) {
      const exact = s.currencies.find(
        c => (c.symbol || "").toUpperCase() === sym && (c.type === "coin" || c.type === "token")
      );
      if (exact?.id) return exact.id;
    }
  } catch { /* continue */ }

  // 2) /coins (reliable)
  const coins = await fetchJSON("https://api.coinpaprika.com/v1/coins");
  const match =
    coins.find(c => (c.symbol || "").toUpperCase() === sym && c.is_active && c.type === "coin") ||
    coins.find(c => (c.symbol || "").toUpperCase() === sym);
  if (match?.id) return match.id;

  // Special-case that bites people:
  if (sym === "QUBIC") return "qu-qubic";

  return null;
}

function fmtUSD(n) {
  if (typeof n !== "number" || !isFinite(n)) return null;
  const dp = n < 1 ? 8 : 2;
  return `$${n.toFixed(dp)}`;
}
const safe = n => (typeof n === "number" && isFinite(n) ? n : null);

// ---------- main ----------
async function getPrices(symbolList, modeStr) {
  const out = { timestamp: new Date().toISOString(), coins: [] };

  // Resolve IDs in parallel
  const resolved = await Promise.all(
    symbolList.map(async sym => {
      try {
        const id = await resolveCoinId(sym);
        return { sym, id };
      } catch (e) {
        return { sym, error: `Lookup failed: ${e.message}` };
      }
    })
  );

  // Fetch tickers in parallel
  out.coins = await Promise.all(
    resolved.map(async ({ sym, id, error }) => {
      if (error) return { symbol: sym, error };
      if (!id) return { symbol: sym, error: "Coin not found" };

      try {
        const t = await fetchJSON(`https://api.coinpaprika.com/v1/tickers/${id}?quotes=USD`);
        const usd = t?.quotes?.USD;
        const price = usd?.price;

        return {
          id,
          name: t?.name || sym,
          symbol: t?.symbol || sym,
          price: safe(price),
          price_formatted: typeof price === "number" ? fmtUSD(price) : null,
          change_1h: safe(usd?.percent_change_1h),
          change_24h: safe(usd?.percent_change_24h),
          change_7d: safe(usd?.percent_change_7d),
          change_display:
            typeof usd?.percent_change_24h === "number"
              ? `${usd.percent_change_24h >= 0 ? "+" : ""}${usd.percent_change_24h.toFixed(2)}%`
              : null,
          market_cap: usd?.market_cap ?? null,
          volume_24h: usd?.volume_24h ?? null,
          last_updated: t?.last_updated || null,
        };
      } catch (e) {
        return { symbol: sym, error: e.message };
      }
    })
  );

  if (String(modeStr).toLowerCase() === "trending") {
    try {
      const g = await fetchJSON("https://api.coinpaprika.com/v1/global");
      out.global = {
        total_market_cap: g?.market_cap_usd ?? null,
        market_cap_change_24h: g?.market_cap_change_24h ?? null,
        bitcoin_dominance: g?.bitcoin_dominance_percentage ?? null,
      };
    } catch (e) {
      out.global_error = e.message;
    }
  }

  return out;
}

// ---------- execute & RETURN STRING in response ----------
const payload = await getPrices(symbols, mode);

// n8n expects `response` to be a STRING. Do not return an object here.
return {
  response: JSON.stringify(payload),
  // Optional extra info for debugging in n8n’s execution view:
  meta: {
    symbols,
    mode,
  },
};

