// DuckBot v2.3.0 - Purple Sunshine News Anchor Enhancement
// Adds Purple Sunshine news anchor overlay to existing trading videos
// This enhances the existing trading analysis workflow without breaking it

const input = $input.first().json;
const videoPath = input.video_path;
const videoFilename = input.video_filename;

// Configuration for Purple Sunshine integration
const COMFYUI_SERVER = "127.0.0.1:8188";
const CLIENT_ID = `n8n_enhance_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const NEWS_ANCHOR_PATH = "C:/Users/Duck1/Desktop/DuckBot Parts/DuckBotAncor/DuckBotNewsAnchor1.png";

// Enhanced ComfyUI workflow to add Purple Sunshine overlay to existing video
function createNewsAnchorOverlayWorkflow(existingVideoPath, newsAnchorPath) {
    return {
        "1": {
            "inputs": {
                "video": existingVideoPath,
                "upload": "video"
            },
            "class_type": "LoadVideo",
            "_meta": {"title": "Load Existing Trading Video"}
        },
        "2": {
            "inputs": {
                "image": newsAnchorPath,
                "upload": "image"
            },
            "class_type": "LoadImage",
            "_meta": {"title": "Load Purple Sunshine News Anchor"}
        },
        "3": {
            "inputs": {
                "video": ["1", 0],
                "overlay_image": ["2", 0],
                "position": "bottom-right",
                "opacity": 0.8,
                "scale": 0.3
            },
            "class_type": "VideoImageOverlay",
            "_meta": {"title": "Add News Anchor Overlay"}
        },
        "4": {
            "inputs": {
                "filename_prefix": "Enhanced_Trading_News",
                "videos": ["3", 0]
            },
            "class_type": "SaveVideo",
            "_meta": {"title": "Save Enhanced Video"}
        }
    };
}

// Function to enhance existing video with Purple Sunshine overlay
async function enhanceVideoWithNewsAnchor() {
    try {
        console.log(`🎭 Adding Purple Sunshine news anchor to trading video: ${videoFilename}`);

        // Check if the video file exists and Purple Sunshine image exists
        if (!videoPath || !videoFilename) {
            console.log('⚠️ No video found to enhance, passing through original data');
            return input;
        }

        // Create enhanced workflow
        const workflow = createNewsAnchorOverlayWorkflow(videoPath, NEWS_ANCHOR_PATH);

        // Queue the enhancement to ComfyUI
        const payload = {
            prompt: workflow,
            client_id: CLIENT_ID
        };

        console.log(`🔄 Sending enhancement request to ComfyUI...`);

        const response = await $http.request({
            method: 'POST',
            url: `http://${COMFYUI_SERVER}/prompt`,
            headers: {
                'Content-Type': 'application/json'
            },
            data: payload,
            timeout: 300000 // 5 minutes
        });

        if (response.status === 200 && response.data && response.data.prompt_id) {
            const promptId = response.data.prompt_id;
            console.log(`✅ Enhancement queued with ID: ${promptId}`);

            // Wait for enhancement to complete
            const maxWaitTime = 180000; // 3 minutes
            const checkInterval = 5000; // 5 seconds
            let elapsedTime = 0;

            while (elapsedTime < maxWaitTime) {
                await new Promise(resolve => setTimeout(resolve, checkInterval));
                elapsedTime += checkInterval;

                try {
                    const historyResponse = await $http.request({
                        method: 'GET',
                        url: `http://${COMFYUI_SERVER}/history/${promptId}`,
                        timeout: 10000
                    });

                    const history = historyResponse.data;
                    if (history && history[promptId] && history[promptId].outputs) {
                        console.log(`🎉 Purple Sunshine enhancement completed!`);

                        // Find the enhanced video file
                        const outputs = history[promptId].outputs;
                        for (const nodeId in outputs) {
                            const nodeOutput = outputs[nodeId];
                            if (nodeOutput.videos && nodeOutput.videos.length > 0) {
                                const enhancedVideo = nodeOutput.videos[0];
                                const enhancedVideoPath = `C:\\Users\\Duck1\\Desktop\\DiscordBotAI\\DiscordBot\\DiscordBot\\ComfyUI_windows_portable_nvidia\\ComfyUI_windows_portable\\ComfyUI\\output\\${enhancedVideo.filename}`;

                                return {
                                    ...input,
                                    video_path: enhancedVideoPath,
                                    video_filename: enhancedVideo.filename,
                                    enhanced_with_purple_sunshine: true,
                                    original_video_path: videoPath,
                                    original_video_filename: videoFilename,
                                    enhancement_prompt_id: promptId
                                };
                            }
                        }
                    }
                } catch (historyError) {
                    console.log(`⏳ Still enhancing... (${elapsedTime/1000}s elapsed)`);
                }
            }

            // If we get here, enhancement timed out
            console.log('⏰ Enhancement timed out, using original video');
            return {
                ...input,
                enhancement_timeout: true,
                attempted_enhancement: true
            };

        } else {
            console.log('⚠️ Failed to queue enhancement, using original video');
            return {
                ...input,
                enhancement_failed: true,
                enhancement_error: `ComfyUI returned status ${response.status}`
            };
        }

    } catch (error) {
        console.error('❌ Error enhancing video with Purple Sunshine:', error.message);
        return {
            ...input,
            enhancement_error: error.message,
            enhancement_failed: true
        };
    }
}

// Execute enhancement
return await enhanceVideoWithNewsAnchor();
